/*
Dragonspine

Original:
https://community.wolfram.com/groups/-/m/t/3529968
https://x.com/yuruyurau

Shadertoy implementation using particle tracking
https://www.shadertoy.com/view/sc3SRH

*/

void main() {
  // copy of https://www.shadertoy.com/view/ffK3z1
  float RES        = resolution.y;
  const float BODY_LENGHT= 435.0;
  float S = RES / 400.0;
  const float alpha = 0.37;
  vec3 pos = vec3(-100.);
  vec4 col = vec4(0.);

  float timer=time*0.65;
  {
    int i=int(vertexId);

    float x = float(i);
    float y = float(i) / BODY_LENGHT;
    float k = (4.0 + sin(y * 2.0 - timer) * 3.0) * cos(x / 29.0);
    float e = y / 8.0 - 13.0;
    float d = sqrt(k * k + e * e);
    if (abs(k) < 1e-5){}
    else{
      float q = 3.0 * sin(k * 2.0)
        + 0.3 / k
        + sin(y / 25.0) * k * (9.0 + 4.0 * sin(e * 9.0 - d * 3.0 + timer * 2.0));
      float c = d - timer;
      // Point position scaled from 400-space into RES-space
      float px = (q + 30.0 * cos(c) + 200.0) * S;
      float py = (400.0 - (q * sin(c) + d * 39.0 - 220.0)) * S;
      // Cull points outside virtual canvas
      if (px < -2.0 || px > RES + 2.0 ||
          py < -2.0 || py > RES + 2.0) {}
      else{
        pos.xy = vec2(px+resolution.x*0.2,py);
        col = vec4(0.60+0.40*sin(vertexId*.003+vec3(0.,2.,4.)+timer*5.),alpha);
        col.rgb=col.rgb*0.5+0.5*sqrt(col.rgb);
        pos.z=1.;
      }
    }
  }
  gl_Position = vec4((pos.xy/resolution.xy)*2.-1., 0., 1.);
  gl_PointSize = .5;


  float snd = texture2D(sound,1.*fract(vec2((0.+0.45*(vertexId/20000.)*(vertexId/20000.)), (0.35+0.205*(sin(3.*vertexId/20000.)))).yx)).x;

  v_color = col;
  snd=1.-min(snd*snd*4.,1.);
  v_color.rgb=mix(v_color.rgb,v_color.rgb*v_color.rgb-1.5*(v_color.rgb-snd)*4.,smoothstep(5.,7.2,timer));
}
